/// An instance of any entity of the schema that can be instantiated.
#[derive(Clone, Debug, PartialEq)]
pub enum Entity {
    /// An [`Group`].
    Group(Box<Group>),
    /// An [`Note`].
    Note(Box<Note>),
    /// An [`Slab`].
    Slab(Box<Slab>),
    /// An [`Wall`].
    Wall(Box<Wall>),
}

impl Entity {
    /// Decodes a record of any entity of the schema that can be instantiated.
    ///
    /// # Errors
    ///
    /// Returns a [`rt::DecodeError`] when the record names no such entity or does not match
    /// its attributes.
    pub fn from_record(record: &rt::Record) -> Result<Self, rt::DecodeError> {
        let index = DECODERS
            .binary_search_by(|(name, _)| (*name).cmp(record.name.as_str()))
            .map_err(|_| rt::DecodeError::UnknownEntity)?;
        (DECODERS[index].1)(record)
    }

    /// Decodes an instance of the data section.
    ///
    /// # Errors
    ///
    /// Returns a [`rt::DecodeError`] for complex instances, and as [`Self::from_record`] does.
    pub fn from_instance(body: &rt::InstanceBody) -> Result<Self, rt::DecodeError> {
        match body {
            rt::InstanceBody::Simple(record) => Self::from_record(record),
            rt::InstanceBody::Complex(_) => Err(rt::DecodeError::ComplexInstance),
        }
    }

    /// The entity name as written in STEP files.
    #[must_use]
    pub fn step_name(&self) -> &'static str {
        match self {
            Self::Group(_) => Group::STEP_NAME,
            Self::Note(_) => Note::STEP_NAME,
            Self::Slab(_) => Slab::STEP_NAME,
            Self::Wall(_) => Wall::STEP_NAME,
        }
    }
}

/// Decoders of every entity that can be instantiated, sorted by STEP name.
type Decoder = fn(&rt::Record) -> Result<Entity, rt::DecodeError>;

const DECODERS: &[(&str, Decoder)] = &[
    ("GROUP", |record| {
        Group::from_record(record).map(Box::new).map(Entity::Group)
    }),
    ("NOTE", |record| {
        Note::from_record(record).map(Box::new).map(Entity::Note)
    }),
    ("SLAB", |record| {
        Slab::from_record(record).map(Box::new).map(Entity::Slab)
    }),
    ("WALL", |record| {
        Wall::from_record(record).map(Box::new).map(Entity::Wall)
    }),
];

#[cfg(test)]
mod tests {
    use super::*;

    const ENTITY_SAMPLES: &str = r#"#1=GROUP('a',*,(#1));
#2=NOTE();
#3=SLAB('a','a',1.,"0",1,.T.,(1,1),#1);
#4=WALL('a','a',1.,.SOLID.,((1.,1.,1.),(1.,1.,1.)),(#1),COUNT(1),.U.);
"#;

    const TYPE_SAMPLES: &str = r#"#1=V(1);
#2=V("0");
#3=V(1);
#4=V(.T.);
#5=V('a');
#6=V(.U.);
#7=V('a');
#8=V(COUNT(1));
#9=V(RATIO(1.));
#10=V((1.,1.));
#11=V(#1);
#12=V(1.);
#13=V((1,1));
#14=V(COUNT(1));
#15=V(KIND(.SOLID.));
#16=V(LABEL('a'));
#17=V(RATIO(1.));
#18=V(#1);
#19=V('a');
#20=V(COUNT(1));
#21=V(KIND(.SOLID.));
#22=V(LABEL('a'));
#23=V(RATIO(1.));
"#;

    fn records(data: &str) -> Vec<rt::Record> {
        let file =
            format!("ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\n{data}ENDSEC;\nEND-ISO-10303-21;\n");
        rt::StepReader::new(file.as_bytes(), rt::Limits::default())
            .unwrap()
            .map(|instance| {
                let rt::InstanceBody::Simple(record) = instance.unwrap().body else {
                    panic!("samples are simple instances");
                };
                record
            })
            .collect()
    }

    fn check_items<T: rt::Decode + Copy + PartialEq + std::fmt::Debug>(items: &[(&str, T)]) {
        for &(name, item) in items {
            let value = rt::Parameter::Enumeration(name.to_owned());
            assert_eq!(rt::decode(&value), Ok(item));
        }
    }

    #[test]
    fn every_entity_decodes_from_a_sample() {
        let records = records(ENTITY_SAMPLES);
        assert_eq!(records.len(), 4);
        for record in &records {
            let entity = Entity::from_record(record).unwrap();
            assert_eq!(entity.step_name(), record.name);
            let body = rt::InstanceBody::Simple(record.clone());
            assert_eq!(Entity::from_instance(&body), Ok(entity));
        }
    }

    #[test]
    fn rejects_unknown_and_complex_instances() {
        let record = rt::Record {
            name: "NOT AN ENTITY".to_owned(),
            parameters: Vec::new(),
        };
        assert_eq!(
            Entity::from_record(&record),
            Err(rt::DecodeError::UnknownEntity)
        );
        let body = rt::InstanceBody::Complex(vec![record]);
        assert_eq!(
            Entity::from_instance(&body),
            Err(rt::DecodeError::ComplexInstance)
        );
    }

    #[test]
    fn every_type_decodes_from_a_sample() {
        let records = records(TYPE_SAMPLES);
        let mut values = records.iter().map(|record| &record.parameters[0]);
        let mut next = || values.next().unwrap();
        assert!(rt::decode::<Amount>(next()).is_ok());
        assert!(rt::decode::<Blob>(next()).is_ok());
        assert!(rt::decode::<Count>(next()).is_ok());
        assert!(rt::decode::<Flag>(next()).is_ok());
        assert!(rt::decode::<Id>(next()).is_ok());
        check_items(Kind::ITEMS);
        assert!(rt::decode::<Known>(next()).is_ok());
        assert!(rt::decode::<Label>(next()).is_ok());
        assert!(matches!(
            rt::decode::<Measure>(next()),
            Ok(Measure::Count(_))
        ));
        assert!(matches!(
            rt::decode::<Measure>(next()),
            Ok(Measure::Ratio(_))
        ));
        check_items(MoreKind::ITEMS);
        assert!(rt::decode::<Pair>(next()).is_ok());
        assert!(matches!(
            rt::decode::<Place>(next()),
            Ok(Place::Instance(1))
        ));
        assert!(rt::decode::<Ratio>(next()).is_ok());
        assert!(rt::decode::<Slots>(next()).is_ok());
        assert!(matches!(rt::decode::<Target>(next()), Ok(Target::Count(_))));
        assert!(matches!(rt::decode::<Target>(next()), Ok(Target::Kind(_))));
        assert!(matches!(rt::decode::<Target>(next()), Ok(Target::Label(_))));
        assert!(matches!(rt::decode::<Target>(next()), Ok(Target::Ratio(_))));
        assert!(matches!(
            rt::decode::<Target>(next()),
            Ok(Target::Instance(1))
        ));
        assert!(rt::decode::<Text>(next()).is_ok());
        assert!(matches!(rt::decode::<Value>(next()), Ok(Value::Count(_))));
        assert!(matches!(rt::decode::<Value>(next()), Ok(Value::Kind(_))));
        assert!(matches!(rt::decode::<Value>(next()), Ok(Value::Label(_))));
        assert!(matches!(rt::decode::<Value>(next()), Ok(Value::Ratio(_))));
        assert!(values.next().is_none());
    }
}
